// Watch list of regulatory URLs to monitor for changes
const WATCH_URLS = [
  {
    url: 'https://www.sebi.gov.in/sebiweb/other/OtherAction.do?doListingSearch=yes&category=13',
    name: 'SEBI ESG Circulars',
    source: 'SEBI'
  },
  {
    url: 'https://www.mca.gov.in/MinistryV2/notification.html',
    name: 'MCA Notifications',
    source: 'MCA'
  },
  {
    url: 'https://sdgs.un.org/goals',
    name: 'UN SDG Updates',
    source: 'UN'
  },
  {
    url: 'https://ghgprotocol.org/news',
    name: 'GHG Protocol News',
    source: 'GHG Protocol'
  },
  {
    url: 'https://mospi.gov.in/national-indicator-framework',
    name: 'MoSPI NIF Updates',
    source: 'MoSPI'
  }
];

return WATCH_URLS.map(item => ({ json: item }));

const crypto = require('crypto');
const content = $json.data || $json.body || '';
const hash = crypto.createHash('sha256').update(content).digest('hex');

return [{
  json: {
    url: $('Fetch Page').item.json.url || '',
    name: $('Build URL Watch List').item.json.name || '',
    source: $('Build URL Watch List').item.json.source || '',
    currentHash: hash,
    contentLength: content.length,
    checkedAt: new Date().toISOString()
  }
}];

const current = $('Compute Content Hash').item.json.currentHash;
const stored = $json.value || null;
const changed = stored !== current && stored !== null;
const isNew = stored === null;

return [{
  json: {
    ...$('Compute Content Hash').item.json,
    previousHash: stored,
    changed,
    isNew,
    shouldAlert: changed || isNew
  }
}];

// Log all results for observability
const results = $input.all();
console.log('Weekly regulatory check complete:', {
  total: results.length,
  changed: results.filter(r => r.json.changed).length,
  new: results.filter(r => r.json.isNew).length
});
return results;
